version:
/ is a full copy of the docs for each past month; listing it
    would put ten near-duplicates of every page in front of crawlers. Archived
    pages stay published and reachable from the version picker. -#}
{%- set archive_prefix = get_url(path="v/") %}

    {%- for sitemap_entry in entries %}
    {%- if sitemap_entry.permalink is not starting_with(archive_prefix) %}

        {{ sitemap_entry.permalink | escape_xml | safe }}
        {%- if sitemap_entry.updated %}
        {{ sitemap_entry.updated }}
        {%- endif %}

    {%- endif %}
    {%- endfor %}
